import gzip
from html import escape
from format_lecon import R,paras
S=gzip.open(R/'ressources_ia/aips/fi_fr/52433.txt.gz','rt').read()
def q(s):return '<blockquote><p>« '+escape(s.strip())+' »</p></blockquote>'
def line(prefix):
 assert prefix in S.splitlines(),prefix;return q(prefix)
def window(l):
 a=S.index('\nBlépharospasme/hémispasme facial\n');b=S.index('\nStrabisme\n',a);dose=S[a:b]
 body=paras('BOTOX est une préparation de toxine botulique de type A. Le traitement du blépharospasme est effectué par un médecin formé aux injections et à l’anatomie périoculaire ; ce n’est pas un collyre ni une mesure pour toute paupière qui tressaute.', 'Les unités sont propres à la préparation, citation AIPS :')+line("Les unités de toxine botulique ne sont pas applicables à d'autres préparations.")+paras('Présentation et âge : flacons de 50 ou 100 unités Allergan. Pour cette indication, la fiche réserve le traitement aux patients de plus de douze ans ; aucune dose n’est extrapolée à un enfant plus jeune.', 'Dose initiale et dose totale maximale, citations AIPS de la rubrique blépharospasme :')+q(next(x for x in dose.splitlines() if x.startswith('Dose recommandée:')))+q(next(x for x in dose.splitlines() if x.startswith('Dose totale maximale:')))+paras('Délai, durée et répétition, citations AIPS :')+q(next(x for x in dose.splitlines() if x.startswith("En général, l'effet initial")))+q(next(x for x in dose.splitlines() if x.startswith("Toutefois, l'injection de plus")))+paras('Les plafonds par œil et par séance/période doivent être respectés ensemble. La réponse clinique et la tolérance guident la séance suivante ; ne pas convertir ces unités en unités d’une autre toxine.', 'Contre-indications générales, citation AIPS :')+q(S[S.index('\nContre-indications\n')+len('\nContre-indications\n'):S.index('Les injections de BOTOX dans le muscle détrusor sont également contre-indiquées:')])+paras('La fiche comporte en outre des contre-indications propres aux injections vésicales, qui ne sont pas présentées comme des contre-indications oculaires.', 'Précautions : la diffusion peut provoquer faiblesse, troubles de déglutition, de parole ou de respiration. Ces symptômes exigent un contact médical immédiat ; une maladie de la jonction neuromusculaire impose une prudence extrême et un avis spécialisé.', 'Au niveau oculaire, ptosis, diplopie et diminution du clignement avec atteinte cornéenne sont possibles. Le spécialiste évite les zones exposant à ces effets et contrôle la surface de l’œil. Prudence en cas d’angle iridocornéen étroit ou de glaucome à angle fermé.', 'Vérifier aminoglycosides, autres médicaments modifiant la transmission neuromusculaire et injections récentes d’une autre toxine. Documenter dose, sites, produit, date, efficacité et tolérance.', 'Grossesse et allaitement, citation AIPS :')+q(S[S.index('\nGrossesse, allaitement\n')+len('\nGrossesse, allaitement\n'):S.index('\nEffet sur l’aptitude')])+paras('La revue Cochrane soutient le bénéfice symptomatique après une séance, avec davantage de ptosis et de troubles visuels. Ses essais ne suffisent pas à établir tous les effets à long terme ; ne pas présenter le traitement comme une guérison définitive.')
 return l.subwindow('botox','BOTOX : dose suisse et sécurité',body,(5,9))
